use vstd::prelude::*;

verus! {
    // Given two equally‐long arrays of i8, produce a boolean array where each entry
    // indicates whether the corresponding elements satisfy a[i] <= b[i].
    fn less_equal(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
        requires
            a.len() == b.len(),
        ensures
            result.len() == a.len(),
        ensures
            forall |i: usize| i < a.len() ==> result[i] == (a[i] <= b[i]),
    {
        let mut result: Vec<bool> = Vec::new();
        let len = a.len();
        let mut i: usize = 0;
        while i < len
            invariant
                i <= len,
                result.len() == i,
                forall |j: usize| j < i ==> result[j] == (a[j] <= b[j]),
            decreases
                len - i,
        {
            // compute the comparison at index i
            let cmp: bool = a[i] <= b[i];
            // append the boolean to the result
            result.push(cmp);
            i = i + 1;
        }
        result
    }
}

